# Manuale utente di YASDE: capitolo 5.

from build import c, note, p, rif, shot, steps, table, tip, ui, ul, warn


S1 = p("Widgets are cards on the desktop. YASDE draws them on the PC with data it reads from the phone. They "
       "are not Android widgets: only the ones in the catalog below exist. Like the taskbar they are dark glass, with white text; "
       "the menus and dialogs stay light.", lead=True) + \
    shot("widgets.png", "«FIG» — The Add widget dialog") + steps([
        "Right-click an empty part of the desktop and choose " + ui("Add widget…") + ".",
        "In the dialog " + ui("Add widget") + " press " + ui("Add") + " on the card you want. The message " + ui("Widget added") + " confirms it. You can add several; close the dialog with " + ui("Done") + ".",
        "A new widget goes to the first free place, starting from the top of the right edge, with a gap of at least 12 pixels from the others. Drag it where you want it: it snaps to a grid of 8 pixels.",
        "Right-click a widget to change it (see below).",
    ]) + ul([
        "<b>Shape.</b> Most widgets are rounded tiles with very soft corners. The analog clock (" + ui("Classic analog") + " and " + ui("Minimal analog") + ") and " + ui("Battery details") + " are round; " + ui("Next alarm") + " and " + ui("Quick switches") + " are capsules (the ends are half circles).",
        "<b>Size.</b> There is no size menu. Move the pointer over a widget: a small corner appears at its bottom right. Drag it to make the widget larger or smaller. The size changes in steps of 8 pixels and the top left corner stays where it is. Each widget has a smallest and a largest size, and it cannot go outside the desktop. Round widgets stay round; a capsule stays at most 128 pixels tall.",
        "<b>From the keyboard.</b> Press Tab until the corner has the focus, then use the arrow keys: each press changes the size by 8 pixels.",
        "<b>More space, more content.</b> A larger widget shows more: for example the storage legend, more notifications or the next days of the weather. What does not fit is left out or cut off.",
        "The right-click menu of a widget has " + ui("Style") + " (for the widgets that have styles), "
        + ui("City") + " (for the dual time zone clock), " + ui("Location…") + " (for the weather) and " + ui("Remove widget") + ".",
        "When you change the style, the size is kept if the new style has the same shape; if the shape changes (for example from the digital clock to an analog one) the widget goes back to a standard size for the new style.",
        "Size, style and position are saved for each phone.",
    ]) + tip("a click on some widgets opens an <b>app</b> of the phone in a YASDE window (see the catalog). It opens the app itself, never a conversation; only two widgets go further and open a precise page, the battery and the storage ones (see the catalog). Each page replaces the one opened before: opening a new page closes the earlier pages of the same window, so they do not pile up. If the phone does not have that app, the click does nothing; a notification is the exception: YASDE always asks the phone to open the app that sent it.")

S2 = table(["Widget", "What it shows", "Notes"], [
    [ui("Clock"), "Time and date.", "Six styles, see below."],
    [ui("Calendar"), "Today: the day number in large letters, then the events of the day, each with a colored bar and its time. The one going on now is marked " + ui("NOW") + ".", "Read-only. Click an event to open the phone's Calendar app, when YASDE knows which app it is. When the widget is narrow the date is written in one line at the top instead."],
    [ui("Phone status"), "Battery level with a bar; larger sizes add " + ui("Network") + ", " + ui("Physical panel") + " and " + ui("Screen") + " (locked or unlocked).", "Values the phone does not give are left empty, never invented. Click to open the phone's Settings app (its main page), when the phone has the Settings app; if the Settings window is already open, it comes to the front. The pointer becomes a hand when the click can work."],
    [ui("Recent notifications"), "The latest notifications of the phone, without opening the panel: for each one the icon of the app (its initials in a colored circle if the icon is not known), the title, the text and the time.", "A notification hidden in YASDE does not count (" + rif("The notifications panel") + "). The larger the widget, the more notifications. Click one to open the app that sent it."],
    [ui("Phone storage"), "The <b>free</b> space in large letters, with the total (" + ui("free of") + " …), a bar divided into colored slices and a legend.", "The slices are images, videos, audio, apps and " + ui("Other") + " (what is used and not counted in the first four). A category the phone cannot report is left out. The bar needs enough height and the legend needs room for all its entries, otherwise it is left out. Click to open the phone's Settings app on its storage page, when the phone has the Settings app. If the Settings window is already open, it comes to the front and switches to that page. If the phone has no such page, the click opens the normal Settings (or just brings an open window to the front). If the Settings window is still opening, or the connection has just dropped, the click only brings the window to the front."],
    [ui("Weather"), "Current conditions and forecast, with the place name.", "Six styles. It uses the Internet: " + rif("The weather widget") + "."],
    [ui("Month calendar"), "The month with a dot on the days that have events; click a day to see its events.", "Three styles: " + ui("Month") + ", " + ui("Week") + ", " + ui("Agenda") + ". Clicking the title or an event opens the phone's Calendar app, when YASDE knows which app it is."],
    [ui("Next alarm"), "A capsule with an amber circle, the time of the phone's next alarm in large letters, and under it the day and how long is left (for example " + ui("Tomorrow · in 7 hours") + ").", ui("No alarm") + " when there is none. Click to open the alarm app, when the phone says which one it is and has it."],
    [ui("Battery details"), "A round widget: a ring with the percentage in the middle and the charging state under it (" + ui("Charging") + ", " + ui("Discharging") + "…). With more room it adds the temperature, the health and the voltage.", "The ring is green; it is coral when the level is 20% or less and the phone is not charging. Values the phone does not give are left out. Click to open the phone's Settings app on its battery page, when the phone has the Settings app. If the Settings window is already open, it comes to the front and switches to that page. If the phone has no such page, the click opens the normal Settings (or just brings an open window to the front). If the Settings window is still opening, or the connection has just dropped, the click only brings the window to the front."],
    [ui("Quick switches"), "A capsule with three round buttons: " + ui("Ringer") + ", " + ui("Do not disturb") + " and " + ui("Flashlight") + ". With enough room the name and the state are written under each button.", "Each click changes the phone: the ringer goes from " + ui("Rings") + " to " + ui("Vibrates") + " to " + ui("Silent") + " and back. A full button means on (for the ringer: rings), only an outline means that the ringer vibrates, an empty button means off (the ringer is silent). A switch the phone does not allow is inactive."],
    [ui("Quick notes"), "A notepad: the title " + ui("Quick notes") + " at the top and under it a text field of several lines, where the text wraps by itself.", "Starts at 250×180 (smallest 200×130, largest 480×640) and is resized from its corner like the others. Drag the widget by the title: from the text field it does not move, because there the mouse selects text. The wheel scrolls the text. Right-click on the text field opens a menu with " + ui("Cut") + ", " + ui("Copy") + ", " + ui("Paste") + ", " + ui("Select all") + " and, after a line, " + ui("Remove widget") + ". " + ui("Cut") + " and " + ui("Copy") + " are off when no text is selected; " + ui("Cut") + " and " + ui("Paste") + " are off when the field cannot be edited (no phone profile). Pasted text follows the same rules and limit as typed text (below). Right-click on the title opens the usual widget menu. There is one text for each phone: several Quick notes widgets show the same text, and when you change phone you see the text of that phone. It is saved while you type (within about a second), before you change phone and when YASDE closes. The limit is 2047 bytes of UTF-8, about 2000 characters, fewer with accented letters or emoji; beyond it nothing more is accepted, not even by pasting. New lines and tabs are kept, other control characters are dropped. The text stays on the PC, in the phone's profile: it is not sent to the phone and does not go in the logs."],
    [ui("Frequent apps"), "The apps you open most often.", "Counted by YASDE for each phone; " + ui("No app opened yet") + " until you open some."],
    [ui("Recent transfers"), "The latest files sent or received in this session.", "Click a received file to open it on the PC, or a sent file to open its folder."],
    [ui("Recent calls"), "The phone's latest calls, newest first. Each row has an icon for the kind of call (incoming, outgoing, missed, declined), the name or, when the number is not in the contacts, the number (" + ui("Hidden number") + " if there is none), the kind of call written under it (" + ui("Incoming") + ", " + ui("Outgoing") + ", " + ui("Missed") + ", " + ui("Declined") + ") and the time: the hour for a call of today, otherwise the day. A missed call is in coral.", "Read-only. The larger the widget, the more rows (the phone gives at most 20). " + ui("No recent calls") + " when the log is empty; " + ui("Not available on this phone") + " when the phone does not give its call log to YASDE. Click a row to open the phone's Phone app, when YASDE finds one of the usual dialer apps on the phone; otherwise the click does nothing. The list is read from the phone about once a minute, and only while this widget is on the desktop."],
    [ui("Network"), "Two blocks. " + ui("Wi-Fi") + ": a signal icon (0 to 4 bars) and the name of the network, or " + ui("Connected") + " when the phone does not tell the name, " + ui("Not connected") + " (Wi-Fi on, no network) or " + ui("Off") + ". " + ui("Mobile") + ": a signal icon and the operator with the generation (for example the operator name, a dot and " + ui("5G") + "), or " + ui("No service") + " or " + ui("No SIM") + ". Under the mobile line " + ui("Mobile data off") + " appears when the phone says that mobile data is off, and the line " + ui("Airplane mode") + " appears when airplane mode is on.", "Read-only: a click does nothing and nothing is changed on the phone. A value the phone does not tell is never guessed: with an unknown mobile data or airplane state the line is simply not shown. " + ui("Not available on this phone") + " when the phone gives nothing. Read about every 15 seconds, only while the widget is on the desktop."],
    [ui("Now playing"), "The track that plays on the phone: title (" + ui("Untitled") + " if there is none), artist and the name of the app, and under them three round buttons, " + ui("Previous track") + ", " + ui("Play or pause") + " and " + ui("Next track") + ". The middle button shows a pause symbol while the music plays and a play symbol when it is paused.", ui("Nothing playing") + " when no player is active (the buttons are off and do nothing); " + ui("Not available on this phone") + " when the phone gives nothing. A button is active only if the player allows that command. The three buttons are the only commands YASDE can send to a player. Click the title to open the app that is playing, when the phone has it. Read about every 3 seconds (and at once after a button), only while the widget is on the desktop."],
], "«TAB» — The widget catalog") + \
    note("one widget is not in the catalog: Find my phone. It is not available in this version.", "Not available.") + \
    note("the names and numbers of the calls, the names of the networks and the titles of the tracks are kept only in the memory of the PC while the widget is open. They are never written on disk and never go in the logs. The new widgets read the phone only while they are on the desktop.", "Privacy.")

S3 = p("Styles change how a widget looks without changing the data. Choose one from the right-click menu, under "
       + ui("Style") + ".", lead=True) + table(["Widget", "Styles"], [
    [ui("Clock"), ui("Digital") + ", " + ui("Classic analog") + " (with a seconds hand), " + ui("Minimal analog") + ", "
     + ui("Flip tiles") + ", " + ui("In words") + " and " + ui("Dual time zone") + ". The last one adds a second city, chosen under "
     + ui("City") + ": " + ui("London") + ", " + ui("New York") + ", " + ui("Los Angeles") + ", " + ui("Moscow") + ", "
     + ui("Dubai") + ", " + ui("Beijing") + ", " + ui("Tokyo") + " or " + ui("Sydney") + ". "
     + ui("No background") + " is the last one: see below."],
    [ui("Month calendar"), ui("Month") + ", " + ui("Week") + ", " + ui("Agenda") + "."],
    [ui("Weather"), ui("Now") + " (icon, temperature, condition, high and low; it grows with the widget: see below), " + ui("Hours") + " (the next hours), "
     + ui("Week") + " (the next days), " + ui("Compact") + " (one line), " + ui("Today") + " (feels like, wind, rain, humidity) and "
     + ui("Curve") + " (the temperature over the next hours) and " + ui("No background") + " (see below)."],
], "«TAB» — Widget styles") + p("The " + ui("Now") + " style of the weather grows with the widget. At the smallest size it shows the icon and the temperature. "
    "With more width it adds the place, the condition and the high and low. With more height it adds the curve of the temperature over the next hours, and with still more height the next days, each with a bar from the low to the high. "
    "The line " + ui("Weather data by Open-Meteo.com") + " is always at the bottom, at every size.") + \
    p("The " + ui("No background") + " style, for the clock and for the weather, has no glass, no fill and no border: the content sits directly on the desktop, in white with a soft dark shadow so that it can be read on any wallpaper. "
      "The clock shows the time in large digits, with the date under it except at the smallest sizes (below 250×128). The weather shows the icon, the temperature, the place and the condition; there is no high and low, no curve and no days, not even when the widget is large. "
      "The line " + ui("Weather data by Open-Meteo.com") + " stays visible. You drag it and resize it from the corner like the tiles. The smallest sizes are 200×112 for the clock and 240×120 for the weather.")

S4 = p("The " + ui("Weather") + " widget is the only part of YASDE that uses the Internet, and only while a weather widget is on the desktop.", lead=True) + ul([
    "The place comes from the phone's position. YASDE asks the phone, which gives a position rounded to about 500 meters; the precise position never leaves the phone. The name of the place is worked out by Android on the phone from that rounded position; on many phones that uses an online service of Google or of the phone's maker.",
    "If the phone does not give a position, the widget says so and offers " + ui("Choose a location…") + ". The same dialog is under " + ui("Location…") + " in the widget menu. Type a city in " + ui("City name") + " and press " + ui("Search") + " (or Enter): the search is sent only when you press it. Pick a result, or " + ui("None") + " to forget the city. A city chosen by hand is used only when the phone gives no position.",
    "The widget always shows " + ui("Weather data by Open-Meteo.com") + " and, in the search dialog, " + ui("Places from GeoNames, via Open-Meteo.com") + ".",
    "While data is being fetched you see " + ui("Updating…") + "; if the service does not answer you see " + ui("Forecast not available") + " and the words “last data at” followed by a time when older data exists.",
]) + warn("adding the widget is the choice: there is no consent dialog. Remove the widget and YASDE stops contacting the weather service. Details are in " + rif("What leaves the PC: the weather") + ".", "Internet.")

CHAPTER = ("Widgets", [
    ("Adding and arranging widgets", S1),
    ("The catalog", S2),
    ("Styles", S3),
    ("The weather widget", S4),
])
